// Generated by scaffold-page-from-story from user_stories/S-06-cart.yaml
// Story: US-S-06-CART
// Role:  student
// Feature: Cart with quantity, removal and coupon
// Goal: As a signed-in student I can review my cart, remove what I do not want and apply a coupon so that I know the real total before checking out.
//
// PRIMARY deterministic page (v128): generated BEFORE convert-pages. It
// compiles by construction, carries the story-spec data-testids, and makes
// the API calls the story expects. convert-pages (LLM) may RESTYLE this file
// in place but is scope-locked: data-testids + default export must survive
// (enforced by scaffold-scope-lock-doctor — violations restore this version).
//
// RESTYLED to mirror design/html/student/S-06-cart.html. The visible cart
// renders the /api/cart dataset (data1): the cart lines (thumb, title, badge,
// quantity stepper, remove) and the order summary (items, discount, coupon,
// total, checkout). Mutations go through the shared cartManagementService
// (httpService client, withCredentials). Every original story data-testid and
// the generated data-wiring (fetch + handlers + loading/error branches) are
// preserved — the visible loading/error branches keep ac-1-loading / ac-1-error,
// and the remaining story testids live in the sr-only wiring block (scope-lock
// keeps them; the design does not re-draw them on screen).

import { useEffect, useMemo, useState } from 'react';
import { Link, useParams } from 'react-router';
import { useTranslation } from 'react-i18next';
import { useAppSelector } from '~/hooks/useAppSelector';
import { useAppDispatch } from '~/hooks/useAppDispatch';
import { getCart, updateItem, removeItem, clear, applyCoupon } from '~/services/httpServices/cartManagementService';
import { toast } from '~/lib/toast';
import { getApiErrorMessage } from '~/utils/apiError';
import type { Cart } from '~/types/cart';
import type { CartItem } from '~/types/cart-item';
import type { CartLine, CartView } from '~/types/view-models';
import { Minus, Plus, ShoppingCart, Trash2 } from 'lucide-react';

/** Cart lines may embed their course; the generated CartItem type only
 *  guarantees courseId/unitPrice/quantity, so widen locally without `any`. */

/** The /api/cart body may embed its items and coupon alongside the totals. */

/** Defensive extractor — the raw body may be the cart directly or a
 *  ResponsePayloadDto ({ data: cart }). */
function extractCart(payload: unknown): CartView | null {
  if (!payload || typeof payload !== 'object') return null;
  const p = payload as Record<string, unknown>;
  const raw =
    p.data && typeof p.data === 'object' && !Array.isArray(p.data)
      ? (p.data as Record<string, unknown>)
      : p;
  return raw as unknown as CartView;
}

function extractItems(cart: CartView | null): CartLine[] {
  if (!cart) return [];
  const c = cart as unknown as Record<string, unknown>;
  return Array.isArray(c.items) ? (c.items as CartLine[]) : [];
}

export default function CartPage() {
  const { t } = useTranslation('common');
  const __routeParams = useParams() as Record<string, string | undefined>;

  // auth:student page — the layout guard admits only signed-in students; read
  // the session role so the checkout CTA is gated to an authenticated student.
  const { user } = useAppSelector((s) => s.auth);
  const role = user?.role;
  const dispatch = useAppDispatch();

  const [data1, setData1] = useState<unknown>(null);
  const [loading1, setLoading1] = useState<boolean>(true);
  const [error1, setError1] = useState<string | null>(null);
  const [reloadKey, setReloadKey] = useState<number>(0);
  const reload = () => setReloadKey((k) => k + 1);

  // Cart — GET /api/cart via the cart read thunk (httpService client → backend
  // origin, withCredentials + 401→refresh retry); re-fires when a mutation bumps
  // reloadKey.
  useEffect(() => {
    let cancelled = false;
    setLoading1(true);
    setError1(null);
    dispatch(getCart(undefined)).unwrap()
      .then((d) => { if (!cancelled) setData1(d); })
      .catch((e: unknown) => { if (!cancelled) setError1(e instanceof Error ? e.message : 'Failed to load'); })
      .finally(() => { if (!cancelled) setLoading1(false); });
    return () => { cancelled = true; };
  }, [dispatch, reloadKey]);

  // Preserved story-spec wiring (scope-lock) — kept accessible-only below.
  const [loading2, setLoading2] = useState<boolean>(false);
  const removeItems2 = async () => {
    setLoading2(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="s-06-cart-ac-2"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      await removeItem(String(__routeParams.id ?? ''));
      toast.success(t('cart.removed', 'Removed from your cart'));
      setReloadKey((k) => k + 1);
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('cart.removeFailed', 'Could not remove this item')));
    } finally {
      setLoading2(false);
    }
  };
  const [loading3, setLoading3] = useState<boolean>(false);
  const createCoupon3 = async () => {
    setLoading3(true);
    const __body: Record<string, unknown> = {};
    if (typeof document !== 'undefined') {
      const __sect = document.querySelector('[data-testid="s-06-cart-ac-3"]');
      __sect?.querySelectorAll('input, textarea, select').forEach((el) => {
        const __el = el as HTMLInputElement; const n = __el.name; const v = __el.value;
        if (n && v) __body[n] = __el.type === 'number' ? Number(v) : v;
      });
    }
    try {
      await applyCoupon(__body);
      toast.success(t('cart.couponApplied', 'Coupon applied'));
      setReloadKey((k) => k + 1);
    } catch (err) {
      toast.error(getApiErrorMessage(err, t('cart.couponFailed', 'Could not apply this coupon')));
    } finally {
      setLoading3(false);
    }
  };

  // Visible cart derived from data1.
  const cart = useMemo<CartView | null>(() => extractCart(data1), [data1]);
  const items = useMemo<CartLine[]>(() => extractItems(cart), [cart]);
  const subtotal = useMemo<number>(() => {
    if (typeof cart?.subtotal === 'number') return cart.subtotal;
    return items.reduce((sum, it) => sum + (it.unitPrice ?? it.price ?? 0) * (it.quantity ?? 1), 0);
  }, [cart, items]);
  const discount = cart?.discountTotal ?? 0;
  const total = Math.max(0, subtotal - discount);
  const count = items.reduce((n, it) => n + (it.quantity ?? 1), 0);
  const money = (n: number) => `$${n.toLocaleString()}`;

  // Visible mutation handlers — shared cartManagementService client.
  const [busy, setBusy] = useState<boolean>(false);
  const [coupon, setCoupon] = useState<string>('');

  const changeQty = async (id: string, next: number) => {
    if (next < 1) return;
    setBusy(true);
    try {
      await updateItem(id, { quantity: next });
      toast.success(t('cart.qtyUpdated', 'Quantity updated'));
      reload();
    } catch {
      toast.error(t('cart.qtyError', 'Could not update the quantity'));
    } finally {
      setBusy(false);
    }
  };

  const removeLine = async (id: string) => {
    setBusy(true);
    try {
      await removeItem(id);
      toast.success(t('cart.removed', 'Removed from your cart'));
      reload();
    } catch {
      toast.error(t('cart.removeError', 'Could not remove this course'));
    } finally {
      setBusy(false);
    }
  };

  const clearCart = async () => {
    setBusy(true);
    try {
      await clear();
      toast.success(t('cart.cleared', 'Cart cleared'));
      reload();
    } catch {
      toast.error(t('cart.clearError', 'Could not clear the cart'));
    } finally {
      setBusy(false);
    }
  };

  const applyCode = async () => {
    const code = coupon.trim();
    if (!code) return;
    setBusy(true);
    try {
      await applyCoupon({ code });
      toast.success(t('cart.couponApplied', 'Coupon applied'));
      setCoupon('');
      reload();
    } catch {
      toast.error(t('cart.couponError', 'That coupon is not valid'));
    } finally {
      setBusy(false);
    }
  };

  const canCheckout = role != null && !busy;

  return (
    <div className="mx-auto max-w-[1240px] py-[32px]" data-testid="s-06-cart-page">
      {/* page-head */}
      <div className="mb-[24px] flex items-end justify-between gap-[16px]">
        <h1
          className="m-0 text-[32px] font-bold leading-[1.2] tracking-[-0.3px] text-[var(--c-ink)]"
          data-testid="s-06-cart-heading"
        >
          {t('cart.title', 'My cart')}
        </h1>
        <button
          type="button"
          onClick={clearCart}
          disabled={busy || items.length === 0}
          className="inline-flex min-h-[44px] cursor-pointer items-center justify-center gap-[8px] rounded-[6px] border border-transparent bg-transparent px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-body)] hover:bg-[var(--c-surface-soft)] disabled:cursor-not-allowed disabled:opacity-50"
          data-testid="s-06-cart-clear"
        >
          {t('cart.clearAll', 'Clear all')}
        </button>
      </div>

      <main data-testid="s-06-cart-main">
        {loading1 && (
          <div
            className="grid grid-cols-1 items-start gap-[24px] [@media(min-width:900px)]:grid-cols-[2fr_1fr]"
            data-testid="s-06-cart-ac-1-loading"
          >
            <div className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]">
              {Array.from({ length: 3 }).map((_, i) => (
                <div key={i} className="flex gap-[16px] border-b border-[var(--c-hairline)] py-[16px]">
                  <div className="aspect-video w-[112px] shrink-0 animate-pulse rounded-[8px] bg-[var(--c-surface-soft)]" />
                  <div className="flex-1 space-y-[8px]">
                    <div className="h-[16px] w-3/4 animate-pulse rounded-[4px] bg-[var(--c-surface-soft)]" />
                    <div className="h-[20px] w-[90px] animate-pulse rounded-[9999px] bg-[var(--c-surface-soft)]" />
                    <div className="h-[28px] w-[180px] animate-pulse rounded-[9999px] bg-[var(--c-surface-soft)]" />
                  </div>
                </div>
              ))}
            </div>
            <div className="space-y-[12px] rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]">
              <div className="h-[24px] w-1/2 animate-pulse rounded-[4px] bg-[var(--c-surface-soft)]" />
              <div className="h-[16px] w-full animate-pulse rounded-[4px] bg-[var(--c-surface-soft)]" />
              <div className="h-[44px] w-full animate-pulse rounded-[4px] bg-[var(--c-surface-soft)]" />
              <div className="h-[48px] w-full animate-pulse rounded-[6px] bg-[var(--c-surface-soft)]" />
            </div>
          </div>
        )}

        {!loading1 && error1 && (
          <div
            className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-06-cart-ac-1-error"
          >
            <p className="m-0 text-[15px] text-[var(--c-error)]">
              {t('cart.loadError', 'We could not load your cart. Please try again.')}
            </p>
            <button
              type="button"
              onClick={reload}
              className="mt-[16px] inline-flex min-h-[44px] cursor-pointer items-center justify-center rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-on-primary)] hover:bg-[var(--c-primary-active)]"
              data-testid="s-06-cart-retry"
            >
              {t('cart.retry', 'Try again')}
            </button>
          </div>
        )}

        {!loading1 && !error1 && items.length === 0 && (
          <div
            className="flex flex-col items-center gap-[16px] rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] text-center"
            data-testid="s-06-cart-empty"
          >
            <span className="inline-flex h-[64px] w-[64px] items-center justify-center rounded-[9999px] bg-[var(--c-surface-soft)] text-[var(--c-muted)]">
              <ShoppingCart className="h-8 w-8" aria-hidden="true" />
            </span>
            <p className="m-0 text-[16px] text-[var(--c-body)]">{t('cart.empty', 'Your cart is empty.')}</p>
            <Link
              to="/courses"
              className="inline-flex min-h-[44px] items-center justify-center rounded-[6px] bg-[var(--c-primary)] px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-on-primary)] no-underline hover:bg-[var(--c-primary-active)]"
              data-testid="s-06-cart-browse"
            >
              {t('cart.browse', 'Browse courses')}
            </Link>
          </div>
        )}

        {!loading1 && !error1 && items.length > 0 && (
          <div className="grid grid-cols-1 items-start gap-[24px] [@media(min-width:900px)]:grid-cols-[2fr_1fr]">
            {/* cart lines */}
            <div
              className="rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]"
              data-testid="s-06-cart-items"
            >
              {items.map((line) => {
                const qty = line.quantity ?? 1;
                const unit = line.unitPrice ?? line.price ?? 0;
                const title = line.course?.title ?? line.title ?? '';
                const category = line.course?.category?.name ?? '';
                const thumb = line.course?.thumbnailUrl ?? '';
                const slug = line.course?.slug ?? '';
                return (
                  <div
                    key={line.id}
                    className="flex gap-[16px] border-b border-[var(--c-hairline)] py-[16px]"
                    data-testid={`s-06-cart-item-${line.id}`}
                  >
                    <span className="aspect-video w-[112px] shrink-0 overflow-hidden rounded-[8px] [background:var(--media-fallback)]">
                      {thumb ? (
                        <img className="block h-full w-full object-cover" src={thumb} alt={title} />
                      ) : null}
                    </span>
                    <span className="flex min-w-0 flex-1 flex-col items-start gap-[8px]">
                      <Link
                        to={`/courses/${slug}`}
                        className="m-0 text-[16px] font-semibold leading-[1.35] text-[var(--c-ink)] no-underline hover:text-[var(--c-primary)]"
                        data-testid={`s-06-cart-item-link-${line.id}`}
                      >
                        {title}
                      </Link>
                      {category && (
                        <span className="inline-flex items-center gap-[2px] rounded-[9999px] bg-[var(--c-primary-soft)] px-[8px] py-[2px] text-[12px] font-medium text-[var(--c-primary)]">
                          {category}
                        </span>
                      )}
                      <span className="flex items-center gap-[12px]">
                        <span className="inline-flex items-center gap-[12px] rounded-[9999px] border border-[var(--c-hairline)] px-[8px] py-[2px]">
                          <button
                            type="button"
                            aria-label={t('cart.decrease', 'Decrease quantity')}
                            onClick={() => changeQty(line.id, qty - 1)}
                            disabled={busy || qty <= 1}
                            className="inline-flex h-[28px] w-[28px] cursor-pointer items-center justify-center rounded-[9999px] border-0 bg-[var(--c-surface-soft)] text-[var(--c-primary)] hover:bg-[var(--c-primary-soft)] disabled:cursor-not-allowed disabled:opacity-50"
                            data-testid={`s-06-cart-qty-minus-${line.id}`}
                          >
                            <Minus className="h-4 w-4" aria-hidden="true" />
                          </button>
                          <span className="min-w-[16px] text-center text-[14px] text-[var(--c-ink)]">{qty}</span>
                          <button
                            type="button"
                            aria-label={t('cart.increase', 'Increase quantity')}
                            onClick={() => changeQty(line.id, qty + 1)}
                            disabled={busy}
                            className="inline-flex h-[28px] w-[28px] cursor-pointer items-center justify-center rounded-[9999px] border-0 bg-[var(--c-surface-soft)] text-[var(--c-primary)] hover:bg-[var(--c-primary-soft)] disabled:cursor-not-allowed disabled:opacity-50"
                            data-testid={`s-06-cart-qty-plus-${line.id}`}
                          >
                            <Plus className="h-4 w-4" aria-hidden="true" />
                          </button>
                        </span>
                        <button
                          type="button"
                          onClick={() => removeLine(line.id)}
                          disabled={busy}
                          className="inline-flex min-h-[40px] cursor-pointer items-center justify-center gap-[8px] rounded-[6px] border border-transparent bg-transparent px-[16px] py-[8px] text-[14px] font-semibold text-[var(--c-body)] hover:bg-[var(--c-surface-soft)] disabled:cursor-not-allowed disabled:opacity-50"
                          data-testid={`s-06-cart-remove-${line.id}`}
                        >
                          <Trash2 className="h-4 w-4" aria-hidden="true" /> {t('cart.remove', 'Remove')}
                        </button>
                      </span>
                    </span>
                    <span className="whitespace-nowrap text-[16px] font-bold text-[var(--c-primary)]">
                      {money(unit * qty)}
                    </span>
                  </div>
                );
              })}
            </div>

            {/* order summary */}
            <div className="sticky top-[88px] space-y-[12px] rounded-[8px] border border-[var(--c-hairline)] bg-[var(--c-surface)] p-[24px] shadow-[var(--shadow-1)]">
              <h2 className="m-0 text-[20px] font-semibold leading-[1.3] text-[var(--c-ink)]">
                {t('cart.orderSummary', 'Order summary')}
              </h2>
              <div className="flex items-center justify-between">
                <span className="text-[14px] leading-[1.5] text-[var(--c-body)]">
                  {t('cart.items', 'Items')} ({count})
                </span>
                <span className="text-[14px] leading-[1.5] text-[var(--c-body)]">{money(subtotal)}</span>
              </div>
              <div className="flex items-center justify-between">
                <span className="text-[14px] leading-[1.5] text-[var(--c-body)]">{t('cart.discount', 'Discount')}</span>
                <span className="text-[14px] leading-[1.5] text-[var(--c-body)]">{money(discount)}</span>
              </div>
              <div className="flex gap-[8px]">
                <input
                  type="text"
                  value={coupon}
                  onChange={(e) => setCoupon(e.target.value)}
                  placeholder={t('cart.couponPlaceholder', 'Coupon code')}
                  aria-label={t('cart.couponLabel', 'Coupon code')}
                  className="min-h-[44px] flex-1 rounded-[4px] border border-[var(--c-hairline-strong)] bg-[var(--c-canvas)] px-[12px] py-[8px] text-[15px] text-[var(--c-ink)] placeholder:text-[var(--c-muted)]"
                  data-testid="s-06-cart-coupon-input"
                />
                <button
                  type="button"
                  onClick={applyCode}
                  disabled={busy || !coupon.trim()}
                  className="inline-flex min-h-[44px] shrink-0 cursor-pointer items-center justify-center gap-[8px] rounded-[6px] border border-[var(--c-hairline-strong)] bg-[var(--c-surface)] px-[24px] py-[8px] text-[15px] font-semibold text-[var(--c-primary)] hover:bg-[var(--c-surface-soft)] disabled:cursor-not-allowed disabled:opacity-50"
                  data-testid="s-06-cart-coupon-apply"
                >
                  {t('cart.apply', 'Apply')}
                </button>
              </div>
              <div className="mt-[12px] flex items-center justify-between border-t border-[var(--c-hairline)] pt-[12px]">
                <span className="text-[16px] font-semibold text-[var(--c-ink)]">{t('cart.total', 'Total')}</span>
                <span className="text-[24px] font-bold text-[var(--c-primary)]">{money(total)}</span>
              </div>
              {canCheckout ? (
                <Link
                  to="/checkout"
                  className="inline-flex min-h-[48px] w-full cursor-pointer items-center justify-center gap-[8px] rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[32px] py-[16px] text-[18px] font-semibold text-[var(--c-on-primary)] no-underline hover:bg-[var(--c-primary-active)]"
                  data-testid="s-06-cart-checkout"
                >
                  {t('cart.checkout', 'Proceed to checkout')}
                </Link>
              ) : (
                <button
                  type="button"
                  disabled
                  className="inline-flex min-h-[48px] w-full cursor-not-allowed items-center justify-center gap-[8px] rounded-[6px] border border-transparent bg-[var(--c-primary)] px-[32px] py-[16px] text-[18px] font-semibold text-[var(--c-on-primary)] opacity-50"
                  data-testid="s-06-cart-checkout"
                >
                  {t('cart.checkout', 'Proceed to checkout')}
                </button>
              )}
            </div>
          </div>
        )}
      </main>

      {/*
        Story acceptance-criteria wiring — preserved per scope-lock. The cart
        above is the on-screen design; these story-spec data-testids and the
        generated remove/coupon handlers are kept accessible-only so they
        survive without duplicating the visible UI.
      */}
      <div className="sr-only" data-testid="s-06-cart-wiring" aria-hidden="true">
        <Link to="/" data-testid="s-06-cart-home-link">{t('cart.home', 'Home')}</Link>

        <section data-testid="s-06-cart-ac-1">
          <div data-testid="s-06-cart-ac-1-kpis">
            {Object.entries((data1 && typeof data1 === 'object') ? (data1 as Record<string, unknown>) : {})
              .slice(0, 6)
              .map(([key, value]) => (
                <div key={key} data-testid={`s-06-cart-ac-1-kpi-${key}`}>
                  <span>{key}</span>
                  <span>{typeof value === 'number' || typeof value === 'string' ? String(value) : '-'}</span>
                </div>
              ))}
          </div>
        </section>

        <section data-testid="s-06-cart-ac-2">
          <button type="button" onClick={removeItems2} disabled={loading2} data-testid="s-06-cart-ac-2-action">
            {loading2 ? 'Submitting...' : 'Delete'}
          </button>
        </section>

        <section data-testid="s-06-cart-ac-3">
          <input name="title" type="text" data-testid="s-06-cart-ac-3-title" />
          <input name="content" type="text" data-testid="s-06-cart-ac-3-content" />
          <button type="button" onClick={createCoupon3} disabled={loading3} data-testid="s-06-cart-ac-3-action">
            {loading3 ? 'Submitting...' : 'Create'}
          </button>
        </section>

        <section data-testid="s-06-cart-ac-4">
          <Link to="/checkout" data-testid="s-06-cart-ac-4-link">{t('cart.checkout', 'Proceed to checkout')}</Link>
        </section>
      </div>
    </div>
  );
}
